// Fetch new notices from TED and keep only what this practice could bid for.
// Plain code, no model. TED's Search API is free and needs no key.
const run = $input.first().json;

// What to ask TED for (the practice profile in data/sample/firm_profile.md)
const CPV = ['71200000', '71400000'];            // architectural services; urban planning and landscape
const COUNTRIES = { DNK: 'DK', SWE: 'SE', NOR: 'NO', DEU: 'DE' };
const FIELDS = ['publication-number', 'notice-title', 'buyer-name', 'organisation-country-buyer',
  'classification-cpv', 'main-classification-proc', 'deadline-receipt-tender-date-lot', 'deadline-receipt-request-date-lot', 'notice-type', 'publication-date', 'links'];
const MAIN_CPV_PREFIXES = ['712', '714'];             // main code must be architectural (712...) or urban planning/landscape (714...)
const PAGE_SIZE = 250;                            // TED maximum per page
const MAX_PAGES = 40;                             // safety stop: 10,000 notices

// Catch-up window: from the last successful run (minus a day), or the last 14 days on the first run
const since = new Date(run.fetched_from).toISOString().slice(0, 10).replace(/-/g, '');
const query = `classification-cpv IN (${CPV.join(' ')}) AND publication-date>=${since}`;

const all = [];
let total = 0;
for (let page = 1; page <= MAX_PAGES; page++) {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.ted.europa.eu/v3/notices/search',
    body: { query, fields: FIELDS, limit: PAGE_SIZE, page },
    json: true,
  });
  const notices = res.notices || [];
  total = res.totalNoticeCount ?? total;
  all.push(...notices);
  if (notices.length < PAGE_SIZE || all.length >= res.totalNoticeCount) break;
  await new Promise(r => setTimeout(r, 500));     // be polite to TED
}

// Safety stop reached before TED's total: saving part of the window as a success would skip the rest. Stop instead.
if (all.length < total) {
  throw new Error(`Fetched ${all.length} of ${total} notices (safety stop: ${MAX_PAGES} pages). Run not marked succeeded.`);
}

// Zero notices for a whole catch-up window almost always means something changed on TED's side (a query or field
// change), not a quiet day. Stop here: the run is not marked succeeded, so the next run retries the same window.
// A false alarm costs one retry; a false success would skip those days for good.
if (all.length === 0) {
  throw new Error(`TED returned 0 notices for publication-date>=${since}. Run not marked succeeded; the next run retries this window.`);
}

const first = v => (Array.isArray(v) ? v[0] : v);
const pickLang = v => {                            // TED gives text per language: prefer English
  if (!v || typeof v !== 'object' || Array.isArray(v)) return first(v) ?? null;
  return first(v.eng ?? v.ENG ?? Object.values(v)[0]) ?? null;
};

const today = new Date().toISOString().slice(0, 10);
const rows = [];
let notArchitecture = 0;
let closed = 0;
for (const n of all) {
  const id = n['publication-number'];
  const country3 = first(n['organisation-country-buyer']);
  if (!COUNTRIES[country3]) continue;                                   // not one of our countries
  const type = String(first(n['notice-type']) ?? '');
  if (type && !type.startsWith('cn')) continue;                         // keep calls for tenders and design contests only
  // TED matches a notice if ANY of its codes is architectural; engineering and works notices often list one as a
  // secondary code. Keep only notices whose MAIN code is architectural or landscape. No main code: keep, let the next step judge.
  const mainCpv = String(first(n['main-classification-proc']) ?? '');
  if (mainCpv && !MAIN_CPV_PREFIXES.some(p => mainCpv.startsWith(p))) { notArchitecture++; continue; }
  // Tender deadline (open procedures) or request-to-participate deadline (restricted procedures, competitions).
  // The earliest one is the date the practice must act by. Some notices state neither; then deadline stays empty.
  const deadlines = [].concat(n['deadline-receipt-tender-date-lot'] ?? [], n['deadline-receipt-request-date-lot'] ?? [])
    .map(d => String(d).slice(0, 10)).sort();
  // The earliest deadline is the first step the practice must take (often the request to participate).
  // Once it has passed, the practice can no longer take part.
  if (deadlines.length && deadlines[0] < today) { closed++; continue; }
  rows.push({
    source_id: id,
    title: pickLang(n['notice-title']) ?? id,
    buyer: pickLang(n['buyer-name']),
    country: COUNTRIES[country3],
    cpv_codes: [...new Set([].concat(n['classification-cpv'] ?? []))],
    deadline: deadlines[0] ?? null,                                     // earliest deadline (date only)
    url: n.links?.html?.ENG ?? `https://ted.europa.eu/en/notice/-/detail/${id}`,
    raw: { ...n, links: undefined },                                    // keep the fields, drop 24-language link lists
  });
}

const noDeadline = rows.filter(r => !r.deadline).length;          // reported each run; a missing deadline never changes the recommendation
return [{ json: { run_id: run.run_id, fetched: all.length, kept: rows.length, not_architecture: notArchitecture, closed, no_deadline: noDeadline, notices: rows } }];
